#include "dexmeguviz/dexmeguviz.h"
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"C scoped line %d: %s\n",__LINE__,#x);return 1;}}while(0)
static unsigned char* readfile(const char* p,long* n){FILE* f=fopen(p,"rb");unsigned char* b;if(!f)return NULL;if(fseek(f,0,SEEK_END)||(*n=ftell(f))<0||fseek(f,0,SEEK_SET)){fclose(f);return NULL;}b=malloc((size_t)*n+1);if(!b||fread(b,1,(size_t)*n,f)!=(size_t)*n){fclose(f);free(b);return NULL;}fclose(f);return b;}
static void binding(const char* tag,const char* label,uint32_t row,uint32_t n,uint32_t node,const dmg_binding_row_v2* b,const dmg_binding_path* path){uint32_t i,relation,source,local,pc;if(b->value.kind==DMG_VALUE_USE){relation=b->value.use.relation;source=b->value.use.source_index;local=b->value.use.caller_ordinal;pc=b->value.use.dex_pc;}else{relation=b->value.entity.relation;source=b->value.entity.source_index;local=b->value.entity.local_index;pc=UINT32_MAX;}printf("%s %s %u %u %u ",tag,label,row,n,node);if(!path->length)putchar('-');for(i=0;i<path->length;++i)putchar(path->sides[i]?'R':'L');printf(" %u %u %u %u %u\n",b->value.kind,relation,source,local,pc);}
int main(int argc,char** argv){unsigned char *dex,*json;long dn,jn;dmg_engine* engine=NULL;dmg_snapshot* snapshot=NULL;dmg_query* query=NULL;dmg_result* result=NULL;dmg_error error={0};dmg_query_info q={0};dmg_relation_info_v2 info={0};dmg_snapshot_overview overview={0};dmg_query_profile profile={0};uint32_t i,j,n;CHECK(argc==4);dex=readfile(argv[1],&dn);json=readfile(argv[2],&jn);CHECK(dex&&json);CHECK(dmg_engine_create(NULL,&engine,&error)==DMG_OK);
 {dmg_source_spec sources[2]={{sizeof(dmg_source_spec),DMG_ABI_VERSION,DMG_INPUT_RAW_DEX,0,dex,(uint64_t)dn,"input:0:a.dex","raw-dex",NULL},{sizeof(dmg_source_spec),DMG_ABI_VERSION,DMG_INPUT_RAW_DEX,0,dex,(uint64_t)dn,"input:1:a.dex","raw-dex",NULL}};dmg_source_set_options opt={sizeof(opt),DMG_ABI_VERSION,"android-jni",0,64,16u<<20};CHECK(dmg_snapshot_open_sources(engine,sources,2,&opt,&snapshot,&error)==DMG_OK);}
 CHECK(dmg_query_compile_json(engine,json,(uint64_t)jn,&query,&error)==DMG_OK);CHECK(dmg_query_execute(snapshot,query,&result,&error)==DMG_OK&&result);CHECK(dmg_result_get_query_info(result,&q)==DMG_OK);CHECK(dmg_result_get_relation_info_v2(result,&info,sizeof(info))==DMG_OK);CHECK(dmg_result_get_overview(result,&overview)==DMG_OK);CHECK(dmg_result_get_profile(result,&profile)==DMG_OK);
 printf("CASE %s %s %s %u %u %u %u %u %llu %u %u\n",argv[3],q.query_id,overview.snapshot_id,info.execution_status,info.coverage,info.decision,info.reason,info.candidates_count,(unsigned long long)info.unknown_rows,profile.scope_complete,profile.scope_source_count);
 for(i=0;i<profile.scope_source_count;++i){uint32_t source;CHECK(dmg_result_get_scope_source(result,i,&source)==DMG_OK);printf("SCOPE %s %u\n",argv[3],source);}
 for(i=0;i<info.candidates_count;++i){dmg_value_row_v2 v={0};CHECK(dmg_result_get_value_v2(result,i,&v,sizeof(v))==DMG_OK&&v.kind==DMG_VALUE_USE);{dmg_use_row* x=&v.use;printf("ROW %s %u %u %u %u %u %u %u %u %u %u %u\n",argv[3],i,x->relation,x->source_index,x->caller_ordinal,x->caller_method_ref,x->dex_pc,x->opcode,x->code_offset,x->target_domain,x->target_index,x->extra_proto);}
  CHECK(dmg_result_get_link_count(result,i,&n)==DMG_OK);for(j=0;j<n;++j){dmg_relation_link_v2 l={0};CHECK(dmg_result_get_link_v2(result,i,j,&l,sizeof(l))==DMG_OK);printf("LINK %s %u %u %u %u %u %u %u %u %u %u %u %u\n",argv[3],i,j,l.node_id,l.key,l.left.relation,l.left.source_index,l.left.local_index,l.left.dex_pc,l.right.relation,l.right.source_index,l.right.local_index,l.right.dex_pc);}
  CHECK(dmg_result_get_binding_count(result,i,&n)==DMG_OK);for(j=0;j<n;++j){dmg_binding_row_v2 v={0};dmg_binding_path path={0};CHECK(dmg_result_get_binding_v2(result,i,j,&v,sizeof(v))==DMG_OK&&dmg_result_get_binding_path(result,i,j,&path,sizeof(path))==DMG_OK);binding("BIND",argv[3],i,j,UINT32_MAX,&v,&path);}
  CHECK(dmg_result_get_proof_binding_count(result,i,&n)==DMG_OK);for(j=0;j<n;++j){dmg_proof_binding_row_v2 v={0};dmg_binding_path path={0};CHECK(dmg_result_get_proof_binding_v2(result,i,j,&v,sizeof(v))==DMG_OK&&dmg_result_get_proof_binding_path(result,i,j,&path,sizeof(path))==DMG_OK);binding("PROOF",argv[3],i,j,v.operator_node,&v.binding,&path);}
 }
 dmg_result_release(result);dmg_query_release(query);dmg_snapshot_release(snapshot);dmg_engine_release(engine);free(dex);free(json);return 0;}
